//! Deterministic Finite Automaton (DFA).
use std::collections::{HashMap, HashSet, VecDeque};

/// A DFA over alphabet of chars.
pub struct Dfa {
    /// transition[(state, symbol)] = next_state
    transitions: HashMap<(usize, char), usize>,
    accept_states: HashSet<usize>,
    start_state: usize,
    states: HashSet<usize>,
}

impl Dfa {
    /// Create a new DFA with given start state.
    pub fn new(start_state: usize) -> Self {
        let mut states = HashSet::new();
        states.insert(start_state);
        Dfa {
            transitions: HashMap::new(),
            accept_states: HashSet::new(),
            start_state,
            states,
        }
    }

    /// Add a state. is_accept: whether it's an accepting state.
    pub fn add_state(&mut self, state: usize, is_accept: bool) {
        unimplemented!()
    }

    /// Add a transition: from state, on symbol, go to target state.
    pub fn add_transition(&mut self, from: usize, symbol: char, to: usize) {
        unimplemented!()
    }

    /// Run the DFA on input string. Returns true if ends in an accept state.
    pub fn accepts(&self, input: &str) -> bool {
        unimplemented!()
    }

    /// Return all states reachable from the start state.
    pub fn reachable_states(&self) -> HashSet<usize> {
        unimplemented!()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// DFA that accepts strings ending with 'b'.
    fn build_ends_with_b() -> Dfa {
        let mut dfa = Dfa::new(0);
        dfa.add_state(0, false);
        dfa.add_state(1, true); // accept state
        dfa.add_transition(0, 'a', 0);
        dfa.add_transition(0, 'b', 1);
        dfa.add_transition(1, 'a', 0);
        dfa.add_transition(1, 'b', 1);
        dfa
    }

    #[test]
    fn test_accepts_valid() {
        let dfa = build_ends_with_b();
        assert!(dfa.accepts("b"));
        assert!(dfa.accepts("ab"));
        assert!(dfa.accepts("aab"));
        assert!(dfa.accepts("abb"));
    }

    #[test]
    fn test_rejects_invalid() {
        let dfa = build_ends_with_b();
        assert!(!dfa.accepts(""));
        assert!(!dfa.accepts("a"));
        assert!(!dfa.accepts("ba"));
        assert!(!dfa.accepts("aba"));
    }

    #[test]
    fn test_unknown_symbol_rejects() {
        let dfa = build_ends_with_b();
        // 'c' has no transition — should reject
        assert!(!dfa.accepts("ac"));
    }

    #[test]
    fn test_reachable_states() {
        let dfa = build_ends_with_b();
        let reachable = dfa.reachable_states();
        assert!(reachable.contains(&0));
        assert!(reachable.contains(&1));
        // Add an unreachable state
        let mut dfa2 = build_ends_with_b();
        dfa2.add_state(99, false); // no transitions to/from 99
        let reachable2 = dfa2.reachable_states();
        assert!(!reachable2.contains(&99));
    }
}
